SELECT p.id, p.wallet_id, p.mint_address, p.opened_at, p.status, p.entry_price, p.quantity, p.trailing_stop_price
FROM paper_positions p
LEFT JOIN ovh_ids o ON p.id = o.id
WHERE o.id IS NULL;
